DROP VIEW IF EXISTS `job_profit_view`;
CREATE ALGORITHM=UNDEFINED DEFINER=`u382513771_admin`@`127.0.0.1` SQL SECURITY DEFINER VIEW `job_profit_view` AS select `job_orders`.`id` AS `id`,`job_orders`.`client_name` AS `client_name`,`job_orders`.`project_name` AS `project_name`,`job_orders`.`grand_total` AS `grand_total`,`job_orders`.`total_cost` AS `total_cost`,coalesce(`job_orders`.`total_cost`,0) - coalesce(`job_orders`.`grand_total`,0) AS `profit`,case when coalesce(`job_orders`.`grand_total`,0) > 0 then round((coalesce(`job_orders`.`total_cost`,0) - coalesce(`job_orders`.`grand_total`,0)) / `job_orders`.`grand_total` * 100,2) else 0 end AS `profit_percentage` from `job_orders`;

